/* ==========================================================================
   Zaverat — Handmade Jewellery Store
   Shared Stylesheet (CSS Variables, Typography, Layout, Header, Footer)
   ========================================================================== */

:root {
  /* Brand Palette */
  --color-bg: #faf7f2;
  --color-surface: #ffffff;
  --color-surface-alt: #f2ece1;
  --color-primary: #8c5a3c;
  --color-primary-dark: #6b4229;
  --color-accent: #c89b3c;
  --color-accent-soft: #f5ebd6;
  --color-text: #2c2420;
  --color-text-muted: #6e625b;
  --color-border: #e3d9cc;
  --color-success: #3b6e4c;
  --color-danger: #a8383b;

  /* Typography */
  --font-serif: Georgia, "Times New Roman", Times, serif;
  --font-sans: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, Roboto, sans-serif;

  /* Spacing & Sizing */
  --container-max: 1200px;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-sm: 0 2px 8px rgba(44, 36, 32, 0.06);
  --shadow-md: 0 8px 24px rgba(44, 36, 32, 0.09);
  --transition: 0.2s ease;
}

/* ===== CHECKOUT MODAL STYLES ===== */
.checkout-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(43, 33, 27, 0.58);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 9999;
}

.checkout-modal-backdrop.hidden {
  display: none !important;
}

.checkout-modal-card {
  background: #FFFFFF;
  color: #2B211B;
  border: 1px solid #E6DDD0;
  border-top: 4px solid #C69C4B;
  border-radius: 12px;
  max-width: 440px;
  width: 100%;
  padding: 28px;
  box-shadow: 0 18px 40px rgba(43, 33, 27, 0.25);
}

.checkout-modal-summary {
  background: #F7F3EB;
  border: 1px solid #E6DDD0;
  border-radius: 8px;
  padding: 14px 16px;
  margin: 16px 0;
}

.checkout-modal-actions {
  display: flex;
  gap: 12px;
  justify-content: flex-end;
  margin-top: 20px;
}

#modal-confirm {
  background: #7B4B2A;
  color: #FFFFFF;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
}

#modal-cancel {
  background: var(--color-surface);
  color: var(--color-text);
  border: 1px solid var(--color-border);
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
}
.checkout-grid {
  display: grid;
  grid-template-columns: 2fr 1fr; /* 60% left, 40% right */
  gap: 2rem;
}
@media (max-width: 768px) {
  .checkout-grid {
    grid-template-columns: 1fr;
  }
}
.checkout-forms .form-group {
  display: flex;
  flex-direction: column;
  margin-bottom: 0.75rem;
}
.checkout-forms .form-group > label {
  margin-bottom: 0.25rem;
  font-weight: 600;
}
.checkout-forms .form-group input,
.checkout-forms .form-group select,
.checkout-forms .form-group textarea {
  padding: 0.5rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
}
.checkout-forms .shipping-method,
.checkout-forms .payment-method {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 0.75rem;
  margin-top: 1rem;
}
.checkout-forms .method-card {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  padding: 0.5rem;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  cursor: pointer;
}
.checkout-forms .method-card:hover,
.checkout-forms .method-card.selected {
  border-color: var(--color-primary);
  background: var(--color-accent-soft);
}
.checkout-forms .method-card input {
  margin-top: 0.2rem;
}
.checkout-forms .payment-details {
  margin-top: 0.5rem;
  padding-left: 1.5rem;
  display: none;
}
.checkout-forms .payment-details.active {
  display: block;
}
.checkout-summary .card {
  padding: 1rem;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
}
.checkout-summary .summary-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
}
.checkout-summary .summary-item img {
  width: 48px;
  height: 48px;
  object-fit: cover;
  border-radius: var(--radius-sm);
}
.checkout-summary .price-breakdown p {
  display: flex;
  justify-content: space-between;
  margin: 0.25rem 0;
}
.checkout-summary .price-breakdown .total {
  font-weight: 700;
  font-size: 1.1rem;
}
.checkout-summary .place-order-btn {
  width: 100%;
  margin-top: 1rem;
  background: var(--color-primary);
  color: #fff;
  border: none;
  padding: 0.75rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  cursor: pointer;
}
.checkout-summary .trust-badges {
  margin-top: 1rem;
  font-size: 0.85rem;
  color: var(--color-text-muted);
}
.hidden { display: none; }

